public class AdivinaNumero {
    public static void main(String[] args) {
        int secreto = 73;
        int[] intentos = {50, 80, 70, 75, 73};
        int idx = 0;
        int intento;
        boolean acierto = false;
        int realizados = 0;

        do {
            intento = intentos[idx++];
            realizados++;
            System.out.print("Intento " + realizados + ": " + intento);
            if (intento == secreto) {
                acierto = true;
                System.out.println(" - ¡Correcto! 🎉");
            } else if (intento < secreto) {
                System.out.println(" - el secreto es mayor");
            } else {
                System.out.println(" - el secreto es menor");
            }
        } while (!acierto && realizados < 5);

        if (!acierto) {
            System.out.println("Sin aciertos. El número era " + secreto);
        }
    }
}

